let counter = 0;

function generateId() {
  counter += 1;
  return `n${counter}`;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note with a title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'The title of the note.' },
          body: { type: 'string', description: 'The body content of the note.' },
        },
        required: ['title', 'body'],
        additionalProperties: false,
      },
    },
    {
      name: 'note_get',
      description: 'Retrieve a stored note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'The id of the note to retrieve.' },
        },
        required: ['note_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    if (!args || typeof args !== 'object') {
      throw new Error('arguments must be an object');
    }
    const { title, body } = args;
    if (!isNonEmptyString(title)) {
      throw new Error('title is required and must be a non-empty string');
    }
    if (!isNonEmptyString(body)) {
      throw new Error('body is required and must be a non-empty string');
    }
    const id = generateId();
    notes.set(id, { id, title, body });
    return {
      content: [
        { type: 'text', text: `Created note ${id}: ${title}\n\n${body}` },
      ],
    };
  }

  if (name === 'note_get') {
    if (!args || typeof args !== 'object') {
      throw new Error('arguments must be an object');
    }
    const { note_id } = args;
    if (!isNonEmptyString(note_id)) {
      throw new Error('note_id is required and must be a non-empty string');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`note not found: ${note_id}`);
    }
    return {
      content: [
        { type: 'text', text: `${note.title}\n\n${note.body}` },
      ],
    };
  }

  throw new Error(`unknown tool: ${name}`);
}
"}

